cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
// Look for any expense-related tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
const expTables = tables.filter(t => t.name.includes('expense') || t.name.includes('EX') || t.name.includes('travel'));
console.log('Expense-related tables:', expTables);
// Check if there's any table with EX001
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM \"' + t.name + '\"').all();
  const match = rows.filter(r => JSON.stringify(r).includes('EX001') || JSON.stringify(r).includes('BostonTech') || JSON.stringify(r).includes('Boston'));
  if (match.length) {
    console.log('\n--- ' + t.name + ' (matches) ---');
    match.forEach(r => console.log(JSON.stringify(r)));
  }
}
db.close();
"

