tool_input_args.value:
cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Comprehensive search: any flight that could connect to BOS
// Check all airports in the system
const allAirports = db.prepare(\"SELECT DISTINCT origin as airport FROM flights UNION SELECT DISTINCT destination as airport FROM flights\").all();
console.log('All airports in the system:', allAirports.map(a => a.airport));

// Any one-stop combinations: flights where dest = some intermediate that has another flight to BOS
// Since BOS doesn't exist at all, this is impossible. But let's confirm.
const toBOS = db.prepare(\"SELECT COUNT(*) as cnt FROM flights WHERE destination='BOS'\").get();
console.log('Flights TO BOS:', toBOS.cnt);
const fromBOS = db.prepare(\"SELECT COUNT(*) as cnt FROM flights WHERE origin='BOS'\").get();
console.log('Flights FROM BOS:', fromBOS.cnt);

db.close();
"
